// Quezon City barangay boundaries and point-in-polygon lookup.
//
// lib/qc-barangays.json is generated by scripts/build-barangay-boundaries.mjs
// from OpenStreetMap (© OpenStreetMap contributors, ODbL). Each feature keeps
// the barangay's official PSGC code. Names are the canonical values stored in
// hydrants/{id}.barangay and stations/{id}.aorBarangays; both sides must use
// exactly these strings because Firestore rules compare them literally.

export interface BarangayFeature {
  type: 'Feature';
  properties: { name: string; psgc: string | null };
  geometry: { type: 'MultiPolygon'; coordinates: number[][][][] };
}

export interface BarangayCollection {
  type: 'FeatureCollection';
  features: BarangayFeature[];
}

/** Lazy client load: ~50 KB gzipped, only needed when pinning or administering AORs. */
export async function loadBarangayBoundaries(): Promise<BarangayCollection> {
  return (await import('./qc-barangays.json')).default as BarangayCollection;
}

function ringContains(ring: number[][], lng: number, lat: number) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if ((yi > lat) !== (yj > lat) && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/** The barangay containing the point, or null outside Quezon City. */
export function barangayAt(boundaries: BarangayCollection, lat: number, lng: number): string | null {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  for (const feature of boundaries.features) {
    for (const [outer, ...holes] of feature.geometry.coordinates) {
      if (ringContains(outer, lng, lat) && !holes.some(hole => ringContains(hole, lng, lat))) {
        return feature.properties.name;
      }
    }
  }
  return null;
}

export function barangayNames(boundaries: BarangayCollection): string[] {
  return boundaries.features.map(feature => feature.properties.name);
}

// Case, accents ("Santo Niño") and punctuation don't matter when searching;
// "U.P. Campus" matches "UP Campus".
const foldName = (text: string) =>
  text.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\./g, '').replace(/[^a-z0-9]+/g, ' ').trim();

/** Search-bar matches: names starting with the query, then a word starting with it, then anywhere. */
export function searchBarangays(boundaries: BarangayCollection, query: string, limit = 3): BarangayFeature[] {
  const q = foldName(query).replace(/^(barangay|brgy|bgy)\b\s*/, '');
  if (q.length < 2) return [];
  const ranked: { feature: BarangayFeature; rank: number }[] = [];
  for (const feature of boundaries.features) {
    const name = foldName(feature.properties.name);
    const rank = name.startsWith(q) ? 0 : name.includes(` ${q}`) ? 1 : q.length >= 3 && name.includes(q) ? 2 : -1;
    if (rank >= 0) ranked.push({ feature, rank });
  }
  ranked.sort((a, b) => a.rank - b.rank || a.feature.properties.name.localeCompare(b.feature.properties.name));
  return ranked.slice(0, limit).map(({ feature }) => feature);
}

/** [west, south, east, north] around the barangay's outer rings. */
export function barangayBounds(feature: BarangayFeature): [number, number, number, number] {
  const box: [number, number, number, number] = [Infinity, Infinity, -Infinity, -Infinity];
  for (const [outer] of feature.geometry.coordinates) {
    for (const [lng, lat] of outer) {
      box[0] = Math.min(box[0], lng);
      box[1] = Math.min(box[1], lat);
      box[2] = Math.max(box[2], lng);
      box[3] = Math.max(box[3], lat);
    }
  }
  return box;
}
